        ),
      );
    }
    if (data.containsKey('inventory_seconds')) {
      context.handle(
        _inventorySecondsMeta,
        inventorySeconds.isAcceptableOrUnknown(
          data['inventory_seconds']!,
          _inventorySecondsMeta,
        ),
      );
    }
    if (data.containsKey('inventory_uses_working_time')) {
      context.handle(
        _inventoryUsesWorkingTimeMeta,
        inventoryUsesWorkingTime.isAcceptableOrUnknown(
          data['inventory_uses_working_time']!,
          _inventoryUsesWorkingTimeMeta,
        ),
      );
    }
    if (data.containsKey('lane_capacity')) {
      context.handle(
        _laneCapacityMeta,
        laneCapacity.isAcceptableOrUnknown(
          data['lane_capacity']!,
          _laneCapacityMeta,
        ),
      );
    }
    if (data.containsKey('label')) {
      context.handle(
        _labelMeta,
        label.isAcceptableOrUnknown(data['label']!, _labelMeta),
      );
    }
    if (data.containsKey('notes')) {
      context.handle(
        _notesMeta,
        notes.isAcceptableOrUnknown(data['notes']!, _notesMeta),
      );
    }
    if (data.containsKey('created_at')) {
      context.handle(
        _createdAtMeta,
        createdAt.isAcceptableOrUnknown(data['created_at']!, _createdAtMeta),
      );
    } else if (isInserting) {
      context.missing(_createdAtMeta);
    }
    if (data.containsKey('updated_at')) {
      context.handle(
        _updatedAtMeta,
        updatedAt.isAcceptableOrUnknown(data['updated_at']!, _updatedAtMeta),
      );
    } else if (isInserting) {
      context.missing(_updatedAtMeta);
    }
    return context;
  }

