      taktValue: taktValue == null && nullToAbsent
          ? const Value.absent()
          : Value(taktValue),
      taktUnit: taktUnit == null && nullToAbsent
          ? const Value.absent()
          : Value(taktUnit),
      theoreticalSeconds: theoreticalSeconds == null && nullToAbsent
