          ..write('needDate: $needDate, ')
          ..write('released: $released, ')
          ..write('delivered: $delivered, ')
          ..write('taktValue: $taktValue, ')
          ..write('taktUnit: $taktUnit, ')
          ..write('theoreticalSeconds: $theoreticalSeconds, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

