    return (StringBuffer('SimulationRunLaneVisit(')
          ..write('runId: $runId, ')
          ..write('studyId: $studyId, ')
          ..write('orderId: $orderId, ')
          ..write('targetId: $targetId, ')
          ..write('stepNodeId: $stepNodeId, ')
          ..write('enteredAt: $enteredAt, ')
          ..write('leftAt: $leftAt')
          ..write(')'))
        .toString();
  }

